ALTER TABLE "action_center_manual_reviews" DROP CONSTRAINT "action_center_manual_bounds";--> statement-breakpoint
ALTER TABLE "action_center_manual_reviews" ADD CONSTRAINT "action_center_manual_bounds" CHECK ("action_center_manual_reviews"."revision" >= 0 and "action_center_manual_reviews"."state" in ('requested','in_progress','resolved') and length("action_center_manual_reviews"."response") between 1 and 2000 and ("action_center_manual_reviews"."state"<>'resolved' or ("action_center_manual_reviews"."resolution" is not null and length("action_center_manual_reviews"."resolution") between 1 and 2000)));